#!/usr/bin/env python3
"""Writes the hedra command files of the firefly meadow's simple models (from art/assets.md, no sheet):
meadow, pond, tree, bush, tuft, flower, stump, net, firefly, moth, spark. Up Z, facing -Y, origin on the
ground under the centre (the net's at its hoop's centre, the insects' at their bodies).
Run from this folder: python3 make_env.py; then `hedra model --text <m>.rmdl run <m>.txt` (build.sh)."""
import math

COL = {  # retrocal-8, sRGB 0..1
    "L": "0.431 0.722 0.659", "D": "0.165 0.345 0.310", "N": "0.455 0.639 0.247", "W": "0.988 1.0 0.753",
    "E": "0.776 0.314 0.353", "V": "0.184 0.078 0.184", "M": "0.467 0.267 0.282", "O": "0.933 0.612 0.365"}

def mats(L, *pairs):
    for name, col in pairs:
        L.append(f"material new {name} --base-color {COL[col]} --no-slot")

def write(name, L):
    L += ["select all", "shade flat", f"export {name}.glb"]
    open(f"{name}.txt", "w").write("\n".join(L) + "\n")

# --- meadow: a top-only plane 15 x 14 m
L = ["# The meadow (generated by make_env.py): a 15 x 14 m plane.", "new"]
mats(L, ("Grass", "D"))
L += ["add mesh plane --name Meadow --size 1 --location 0 0 0", "scale 15 14 1", "apply --scale", "material assign Grass"]
write("meadow", L)

# --- pond: dark water, a rim of stones, three lily pads, the moon's reflection (unlit)
L = ["# A pond (generated by make_env.py), 3.2 x 2.2 m.", "new"]
mats(L, ("Water", "V"), ("Stone", "M"), ("Pad", "N"), ("Moon", "W"))
L += ["add mesh cylinder --name Water --vertices 10 --radius 1.6 --depth 0.04 --location 0 0 0.02", "scale 1 0.7 1",
      "apply --scale", "material assign Water"]
for k in range(10):
    a = 2 * math.pi * k / 10 + 0.2
    L += [f"add mesh ico-sphere --name Stone{k} --subdivisions 1 --radius {0.16 + 0.05 * (k % 3)} "
          f"--location {1.68 * math.cos(a):.2f} {1.18 * math.sin(a):.2f} 0.05", "material assign Stone"]
for k, (x, y, r) in enumerate(((-0.7, 0.2, 0.26), (0.5, -0.35, 0.22), (0.2, 0.42, 0.18))):
    L += [f"add mesh cylinder --name Pad{k} --vertices 7 --radius {r} --depth 0.03 --location {x} {y} 0.05",
          "material assign Pad"]
L += ["add mesh cylinder --name Moon --vertices 10 --radius 0.3 --depth 0.02 --location 0.55 0.25 0.045",
      "scale 1 0.7 1", "apply --scale", "material assign Moon"]
write("pond", L)

# --- tree: a dark round-crowned tree, 4.2 m
L = ["# A tree (generated by make_env.py), 4.2 m.", "new"]
mats(L, ("Bark", "M"), ("Leaf", "D"))
L += ["add mesh cylinder --name Trunk --vertices 6 --radius 0.22 --depth 2.0 --location 0 0 1.0", "material assign Bark"]
for k, (x, y, z, r) in enumerate(((0, 0, 2.9, 1.25), (-0.8, 0.3, 2.3, 0.85), (0.75, -0.25, 2.4, 0.9), (0.1, 0.5, 3.6, 0.75))):
    L += [f"add mesh ico-sphere --name Crown{k} --subdivisions 1 --radius {r} --location {x} {y} {z}", "material assign Leaf"]
write("tree", L)

# --- bush: three low leaf balls
L = ["# A bush (generated by make_env.py), 1.6 m across.", "new"]
mats(L, ("Leaf", "D"))
for k, (x, y, r) in enumerate(((0, 0, 0.6), (-0.55, 0.1, 0.42), (0.55, -0.1, 0.45))):
    L += [f"add mesh ico-sphere --name Ball{k} --subdivisions 1 --radius {r} --location {x} {y} {r * 0.7:.2f}", "material assign Leaf"]
write("bush", L)

# --- tuft: a clump of five tall grass blades (thin pyramids), 0.6 m
L = ["# A grass tuft (generated by make_env.py).", "new"]
mats(L, ("Blade", "N"))
for k in range(5):
    a = 2 * math.pi * k / 5
    L += [f"add mesh cone --name Blade{k} --vertices 3 --radius1 0.06 --radius2 0 --depth {0.45 + 0.08 * (k % 3):.2f} "
          f"--location {0.1 * math.cos(a):.2f} {0.1 * math.sin(a):.2f} 0.25 --rotation {12 * math.cos(a):.1f} {12 * math.sin(a):.1f} 0",
          "material assign Blade"]
write("tuft", L)

# --- flower: a stalk and a five-petal head (red), 0.5 m
L = ["# A flower (generated by make_env.py).", "new"]
mats(L, ("Stalk", "D"), ("Petal", "E"), ("Heart", "O"))
L += ["add mesh cylinder --name Stalk --vertices 4 --radius 0.03 --depth 0.45 --location 0 0 0.22", "material assign Stalk",
      "add mesh cylinder --name Petals --vertices 5 --radius 0.16 --depth 0.05 --location 0 0 0.46", "material assign Petal",
      "add mesh ico-sphere --name Heart --subdivisions 1 --radius 0.06 --location 0 0 0.5", "material assign Heart"]
write("flower", L)

# --- stump: a sawn tree stump the jar stands on, 0.9 m across, 0.5 m tall, with two roots
L = ["# A stump (generated by make_env.py), its top at 0.5 m.", "new"]
mats(L, ("Bark", "M"), ("Rings", "O"))
L += ["add mesh cylinder --name Stump --vertices 8 --radius 0.45 --depth 0.48 --location 0 0 0.24", "material assign Bark",
      "add mesh cylinder --name Top --vertices 8 --radius 0.42 --depth 0.04 --location 0 0 0.49", "material assign Rings"]
for k, a in enumerate((0.4, 2.6)):
    L += [f"add mesh cube --name Root{k} --size 1 --location {0.48 * math.cos(a):.2f} {0.48 * math.sin(a):.2f} 0.08",
          "scale 0.35 0.16 0.16", "apply --scale", f"set rotation 0 0 {math.degrees(a):.1f}", "material assign Bark"]
write("stump", L)

# --- net: a butterfly net, its origin at the hoop's centre: a wire hoop 0.84 m across lying flat, a
# deep cream bag hanging under it (two-sided), a handle running back towards the camera (+Z in the
# scene: hedra -Y) and up
L = ["# A butterfly net (generated by make_env.py), origin at the hoop's centre.", "new"]
mats(L, ("Hoop", "M"), ("Mesh", "L"), ("Handle", "O"))
L += ["add mesh torus --name Hoop --major-segments 12 --minor-segments 4 --major-radius 0.42 --minor-radius 0.045 --location 0 0 0",
      "material assign Hoop",
      "add mesh cone --name Bag --vertices 10 --radius1 0.06 --radius2 0.4 --depth 0.55 --location 0 0 -0.3 --cap-fill none",
      "material assign Mesh",
      "add mesh cylinder --name Handle --vertices 5 --radius 0.04 --depth 1.5 --location 0 -1.1 0.45 --rotation -60 0 0",
      "material assign Handle"]
write("net", L)

# --- firefly: a glowing abdomen (cream) and a small orange head, 0.2 m (unlit in the bake)
L = ["# A firefly (generated by make_env.py), origin at its glow.", "new"]
mats(L, ("Glow", "W"), ("Head", "O"))
L += ["add mesh ico-sphere --name Glow --subdivisions 1 --radius 0.095 --location 0 0 0", "material assign Glow",
      "add mesh ico-sphere --name Head --subdivisions 1 --radius 0.06 --location 0 -0.11 0.03", "material assign Head"]
write("firefly", L)

# --- moth: a fat body and two broad wings (two-sided), 0.6 m wingspan
L = ["# A moth (generated by make_env.py), origin at its body.", "new"]
mats(L, ("Body", "V"), ("Wing", "M"), ("Spot", "E"))
L += ["add mesh ico-sphere --name Body --subdivisions 1 --radius 0.09 --location 0 0 0", "scale 0.8 1.6 0.8", "apply --scale",
      "material assign Body"]
for s in (-1, 1):
    L += [f"add mesh cylinder --name Wing{'LR'[s > 0]} --vertices 5 --radius 0.17 --depth 0.03 --location {s * 0.18} 0.02 0.02",
          "scale 1.1 0.9 1", "apply --scale", "material assign Wing",
          f"add mesh cylinder --name Spot{'LR'[s > 0]} --vertices 4 --radius 0.06 --depth 0.035 --location {s * 0.2} 0.0 0.025",
          "material assign Spot"]
write("moth", L)

# --- spark: a four-pointed twinkle (unlit), for catches
L = ["# A twinkle (generated by make_env.py).", "new"]
mats(L, ("Spark", "W"))
for k, rot in enumerate(((0, 0, 0), (90, 0, 0), (0, 90, 0))):
    L += [f"add mesh cube --name Ray{k} --size 1 --location 0 0 0", "scale 0.06 0.06 0.5", "apply --scale",
          f"set rotation {rot[0]} {rot[1]} {rot[2]}", "material assign Spark"]
write("spark", L)
print("wrote meadow pond tree bush tuft flower stump net firefly moth spark .txt")
